import { course, teacher, testimonials, results } from '../config.js';
import { eyebrow, purchase, arrow, check, esc } from './ui.js';
export function Story() {
 const problems = ['Nie wiesz, od czego zacząć.', 'Na myśl o maturze czujesz stres.', 'Znasz słowa, ale trudno Ci mówić.', 'Pisanie zajmuje Ci wieczność.', 'Wciąż wracają te same błędy.', 'Kolejny arkusz? Może jutro.'];
 const outcomes = ['Masz jasny plan aż do matury.', 'Wiesz, czego spodziewać się w arkuszu.', 'Ćwiczysz mówienie, krok po kroku.', 'Piszesz i wiesz, co poprawić.', 'Rozumiesz błędy dzięki feedbackowi.', 'Regularność zastępuje odkładanie.'];
 return `<section id="zaczynamy" class="section problem-section"><div class="container"><div class="section-heading reveal">${eyebrow('01', 'BRZMI ZNAJOMO?')}<h2>Dużo materiału. <br>Mało pewności, <span class="purple">co dalej.</span></h2><p>Nie musisz ogarniać wszystkiego samodzielnie. <br>Potrzebujesz planu, praktyki i kogoś, kto Cię poprowadzi.</p></div><div class="change-grid reveal"><div class="before"><span class="small-label">TERAZ BYWA TAK</span><ul>${problems.map(p=>`<li><span aria-hidden="true">↯</span>${p}</li>`).join('')}</ul><span class="handwritten">Spokojnie. Da się to poukładać.</span></div><div class="change-arrow" aria-hidden="true">${arrow}</div><div class="after"><span class="small-label">Z KURSEM ZACZYNA SIĘ ZMIANA</span><ul>${outcomes.map(p=>`<li>${check}${p}</li>`).join('')}</ul><span class="small-label after-note">MNIEJ CHAOSU. WIĘCEJ KROKÓW DO PRZODU.</span></div></div></div></section>`;
}
export function Program() {
 const steps = [ ['Sprawdzamy, gdzie jesteś', 'Zaczynamy od sprawdzenia poziomu i Twoich potrzeb. To punkt wyjścia do wspólnej pracy.'], ['Wybieramy kierunek', 'Podstawa czy rozszerzenie? Potwierdzamy poziom matury i dopasowujemy grupę oraz termin.'], ['Łapiemy regularny rytm', 'Spotykamy się online raz w tygodniu. Pracujesz z zadaniami, mówisz i pytasz — aktywnie.'], ['Zamieniamy błędy w postęp', 'Między zajęciami wykonujesz zadania. Otrzymujesz konkretne wskazówki i powtarzasz materiał przed maturą.'] ];
 const lesson = [ ['10', 'Rozgrzewka językowa', 'Krótka rozmowa, powtórka, wejście w angielski.'], ['20', 'Zadania maturalne', 'Praca z formatem egzaminu i strategiami rozwiązywania.'], ['20', 'Angielski w praktyce', 'Speaking, słownictwo lub gramatyka w kontekście.'], ['10', 'Feedback i dalszy plan', 'Analiza błędów i konkretne kroki na kolejny tydzień.'] ];
 return `<section id="program" class="section program-section"><div class="container"><div class="split-heading reveal"><div>${eyebrow('02','TWÓJ PLAN DO MATURY')}<h2>Jeden cel. <br><span class="purple">Małe, regularne kroki.</span></h2></div><p>Bez nauki na ostatnią chwilę. <br>Z harmonogramem, który prowadzi Cię <br>przez przygotowania do matury ${course.year}.</p></div><div class="steps reveal">${steps.map((s,i)=>`<article class="step"><span class="step-number">0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div><div class="lesson-board reveal"><div class="lesson-intro"><p class="small-label">TAK WYGLĄDA NASZE SPOTKANIE</p><h3><strong>60</strong> minut. <br>Całkiem dużo <br><span>dla Twojego angielskiego.</span></h3><p>Przykładowy plan zajęć. <br>Proporcje dopasowujemy do tematu i potrzeb grupy.</p><div class="lesson-clock" aria-hidden="true"><span>60′</span></div></div><div class="lesson-timeline">${lesson.map(s=>`<article><div class="minute"><b>${s[0]}</b><span>MIN</span></div><div><h4>${s[1]}</h4><p>${s[2]}</p></div></article>`).join('')}</div></div></div></section>`;
}
export function Value() {
 return `<section id="w-kursie" class="section value-section"><div class="container"><div class="split-heading reveal"><div>${eyebrow('03','WIĘCEJ NIŻ SAMO SPOTKANIE')}<h2>Wszystko, czego potrzebujesz. <br><span class="purple">W jednym rytmie.</span></h2></div><p>Przychodzisz na zajęcia. <br>Wiesz, co robić pomiędzy nimi. <br>I nie zostajesz z błędami bez odpowiedzi.</p></div><div class="value-grid"><article class="value-item reveal"><div class="material-art paper-art" aria-hidden="true"><div class="mini-paper"><span>ENGLISH / WORKSHEET 01</span><b>Practice makes <br>progress.</b><div class="paper-line"></div><div class="paper-line short"></div><p>01 &nbsp; Read. Think. Try.</p><div class="paper-options">A <i></i> B <i class="selected"></i> C <i></i></div></div><div class="paper-tab">YOUR NEXT STEP ↗</div><span class="paper-pen"></span></div><span class="small-label">01 / DOBRZE DOBRANE MATERIAŁY</span><h3>Otwierasz. I działasz.</h3><p>Zadania w formacie maturalnym, słownictwo i gramatyka w praktyce. Materiały masz w cenie kursu.</p></article><article class="value-item reveal"><div class="material-art feedback-art" aria-hidden="true"><div class="mini-feedback"><span>TWÓJ FEEDBACK</span><p>I <s>am agree</s> <strong>agree</strong> <br>with this idea.</p><div>✓ Dobry argument! <br><span>„Agree” to czasownik — bez „am”.</span></div></div><span class="feedback-badge">AHA! TERAZ ROZUMIEM.</span></div><span class="small-label">02 / KONKRETNY FEEDBACK</span><h3>Wiesz, co poprawić.</h3><p>Szczegółowe wskazówki do pisania i mówienia. Zauważasz powtarzające się błędy i pracujesz nad nimi.</p></article><article class="value-item reveal"><div class="material-art speaking-art" aria-hidden="true"><div class="headphones"><span></span><i></i><b></b></div><div class="speaking-bubble">Let’s talk.</div><div class="speaking-response">I think… <span>✦</span></div></div><span class="small-label">03 / PRZESTRZEŃ NA MÓWIENIE</span><h3>Twój głos ma znaczenie.</h3><p>Maksymalnie 6 osób w grupie to przestrzeń na konwersacje, pytania i indywidualne wskazówki.</p></article></div><div class="value-bottom reveal"><p>${check} Regularne prace domowe <span>+</span> materiały <span>+</span> wskazówki do dalszej nauki</p>${purchase('Chcę tak się uczyć')}</div></div></section><section class="beyond-section"><div class="container beyond-inner reveal"><div><p class="eyebrow">MATURA TO POCZĄTEK</p><h2>Angielski zostaje. <br><span>Dużo dłużej niż wynik.</span></h2></div><div class="beyond-content"><p>Na wyjeździe. Na studiach. W pierwszej pracy. <br>Uczysz się języka, z którego naprawdę korzystasz.</p><div class="word-tags"><span>swobodne rozmowy ↗</span><span>podróże</span><span>studia za granicą</span><span>filmy bez napisów</span><span>nowe możliwości</span></div></div></div></section>`;
}
export function Teacher() {
 return `<section id="prowadzaca" class="section teacher-section"><div class="container teacher-grid"><div class="teacher-visual reveal"><div class="teacher-photo"><img src="${course.aboutImage}" alt="Prowadząca kurs uśmiechająca się podczas pracy z laptopem" width="1300" height="1733" loading="lazy"></div><span class="teacher-sticker">Po Twojej stronie.<span aria-hidden="true">✳</span></span><span class="handwritten teacher-note">Najpierw człowiek. <br>Potem podręcznik.</span></div><div class="teacher-copy reveal">${eyebrow('04','POZNAJMY SIĘ')}<h2>Poznaj osobę, która pomoże Ci przejść przez przygotowania <span class="purple">krok po kroku.</span></h2><p class="teacher-belief">Angielski to coś więcej niż podręcznik i wynik egzaminu. Skuteczna nauka opiera się na regularności, praktyce, dobrym feedbacku i atmosferze, w której nie boisz się popełniać błędów.</p><div class="teacher-details"><h3>${esc(teacher.name)}</h3><p>${esc(teacher.bio)}</p><div><span>KWALIFIKACJE</span><p>${esc(teacher.qualifications)}</p></div><div><span>DOŚWIADCZENIE</span><p>${esc(teacher.experience)}</p></div><p class="teacher-quote">${esc(teacher.quote)}</p></div></div></div></section>`;
}
export function SocialProof() {
 return `<section class="proof-section"><div class="container reveal"><div class="proof-title"><span class="proof-asterisk" aria-hidden="true">✳</span><div><p class="small-label">PRAWDZIWE HISTORIE. PRAWDZIWE POSTĘPY.</p><h2>Tu będzie miejsce na Wasze głosy.</h2></div></div>${testimonials.length ? `<div class="testimonials">${testimonials.map(t=>`<figure><blockquote>${esc(t.quote)}</blockquote><figcaption>${esc(t.name)} · ${esc(t.context)}</figcaption></figure>`).join('')}</div>` : '<p class="proof-empty">Opinie uczestników pojawią się tutaj po ich otrzymaniu i za zgodą autorów. <br>Na razie poznaj sposób pracy i sprawdź, czy ten kurs jest dla Ciebie.</p>'}${results.length ? `<div class="results">${results.map(r=>`<p><strong>${esc(r.value)}</strong>${esc(r.label)}</p>`).join('')}</div>` : ''}</div></section>`;
}
